def max_len_sub(arr, k):
    n = len(arr)
    dp = [[0] * n for _ in range(n)]
    for i in range(n):
        dp[i][i] = 1
    for i in range(n - 1, -1, -1):
        for j in range(i + 1, n):
            if abs(arr[i] - arr[j]) <= k:
                dp[i][j] = max(dp[i][j], dp[i + 1][j] + 1)
            else:
                dp[i][j] = max(dp[i][j], dp[i + 1][j])
    return dp[0][n - 1]

