        dp.append([grid[0][i], grid[0][i] + grid[1][i]])
    # Iterate over the rest of the rows
    for i in range(1, len(grid)):
        # Initialize the current row's dp
        dp.append([grid[i][0], grid[i][1]])
        # Iterate over the previous rows
        for j in range(len(dp)):
