    n = len(prices)
    dp = [[[0 for _ in range(k+1)] for _ in range(n)] for _ in range(n)]
    for i in range(n):
        dp[i][i][0] = 0
    for l in range(2, n+1):
        for i in range(n-l+1):
            j = i + l - 1
            dp[i][j][0] = max(dp[i+1][j][0], dp[i][j-1][0])
            for m in range(1, k+1):
