        for i in range(target, num - 1, -1):
            dp[i] = dp[i] or dp[i - num]

    return dp[target]

import re

def match(string):
    pattern = re.compile(r'[A-Z][a-z]+')
    match = pattern.search(string)
    if match:
        return 'Yes'
    else:
        return 'No'

def first_Factorial_Divisible_Number(x):
    n = 1
    while True:
        if factorial(n) % x == 0:
            return n
        n += 1

def factorial(n):
    if n == 0:
        return 1
    else:
        return n * factorial(n-1)

def remove_matching_tuple(tuple1, tuple2):
    result = []
    for item in tuple1:
        if item not in tuple2:
            result.append(item)
    return result

def largest_palindrome(arr, n):
    max_num = 0
    for i in range(n):
        for j in range(i+1, n):
            if is_palindrome(arr[i], arr[j]):
                max_num = max(max_num, arr[i] * arr[j])
    return max_num

def is_palindrome(num1, num2):
    return str(num1) == str(num1)[::-1] and str(num2) == str(num2)[::-1]

def sort_tuple(tuples):
    tuples.sort(key=lambda x: x[1])
    return tuples

def frequency_Of_Largest(arr):
    max_val = max(arr)
    count = 0
    for i in arr:
        if i == max_val:
            count += 1
    return count

def extract_symmetric(lst):
    result = set()
    for i in range(len(lst)):
        for j in range(i+1, len(lst)):
            if lst[i][0] == lst[j][1] and lst[i][1] == lst[j][0]:
                result.add((lst[i], lst[j]))
    return result

def binary_search(arr, x): 
    l = 0
    r = len(arr) - 1
    while l <= r: 
        mid = l + (r - l) // 2
        if arr[mid] == x: 
            return mid 
        elif arr[mid] < x: 
            l = mid + 1
        else: 
            r = mid - 1
    return -1

def binary_to_integer(binary_tuple):
    binary_str = ''.join(str(x) for x in binary_tuple)
    return int(binary_str, 2)

import re

def remove_lowercase(string):
    return re.sub(r'[a-z]', '', string)

import heapq

def heap_queue_smallest(nums, k):
    heap = []
    for num in nums:
        heapq.heappush(heap, num)
    smallest = []
    for _ in range(k):
        smallest.append(heapq.heappop(heap))
    return smallest

def gcd(a, b):
    if a == 0:
        return b
    return gcd(b % a, a)

def concatenate_elements(lst):
    result = ""
    for element in lst:
        result += element
    return result

def sum_Of_Series(n):
    sum = 0
    for i in range(1, n+1):
        sum += i**3
    return sum

def re_order(arr):
    non_zero = []
    for i in arr:
        if i != 0:
            non_zero.append(i)
    return non_zero + [0] * (len(arr) - len(non_zero))

def same_order(list1, list2):
    if len(list1) != len(list2):
        return False
    for i in range(len(list1)):
        if list1[i] != list2[i]:
            return False
    return True

def average_Odd(n):
    total = 0
    for i in range(1, n+1, 2):
        total += i
    return total / n

def no_of_subsequences(arr, k):
    count = 0
    for i in range(len(arr)):
        for j in range(i+1, len(arr)):
            if arr[i]*arr[j] < k:
                count += 1
    return count
